INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p88509-swe399', 'stk-explicit', 'SWE 399', 'info', '{"desc": "صحيح … طلاب الـ ICS و الـ SWE إلى الآن قريدهم IC …\nطبعاً المشرف على التدريب الصيف الماضي للتخصصين هذي هو الدكتور الدرو … وهو معروف بأنه من النوع الـ lazy والمسوف في المواعيد بالرغم من عقليته الصاروخية - دبل ميجر وفيرست أونر - 🙂\nلكن إلى الآن ما نزل القريدات !!\nبس تطمن يعني معقول بيعطيك fail ؟ اذا انت مسلّم الريبورت ومسوي بريسنتيشن ومسلم البروقريس ريبورتس كلها والإيفالويشن فما اعتقد انه فيها fail …\nانا قاللي الدكتور اللي سويت له البريسنتيشن: ( you passed … 10/10 )\nلكن الله يستر ماني مصدق الين ما اشوف الـ IC تصير P أو Pass …\n\nمع السلامة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/49580/4", "user": "eXplicit", "ts": 1138101873000, "tid": 49580, "pn": 4}}', 1138101873000, 1794792308, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1282363-swe399', 'stk-korabeka', 'SWE 399', 'info', '{"desc": "وعليكم السلام ورحمة الله وبركاته\n\nالله يوفقك ويسهل أمرك\n\nأنا اشتغلت معهم التدريب الصيفي 2010 … وكان شغلهم ديزاين وشغالين على سوفتويرز وماسكين وقتها شركة كيآن … ومشاريع ثانية\nوعندهم مكاتب في كل ديرة والمقر الرئيسي أمريكا …\n\nمن ناحية الراتب … مثل ما قال الأخ iEymn\n\nحاول تقنعهم يزيدون راتبك بطريقة دبلوماسية\nوإن ما قدرت فالشركة سمعتها طيبة وتكسب خبرة وإذا حصلت عرض أفضل تقدر تستقيل\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/flour-arabia/151569/8", "user": "koRaBeKa", "ts": 1383556984000, "tid": 151569, "pn": 8}}', 1383556984000, 1794792308, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
